# ----------------------------- Imports ----------------------------- ## Testing frameworkimport pytest  # Main testing libraryfrom unittest.mock import patch, MagicMock  # For mocking MongoDB client and simulating behaviorimport pymongo.errors  # To simulate common MongoDB exceptions# Import the database wrapper and its related custom exceptions for validationfrom backend.utils.database import (    Database,    DatabaseConnectionError,    DataInsertionError,    DataRetrievalError,    CollectionAccessError)# ----------------------------- Global Fixture ----------------------------- #@pytest.fixture(autouse=True)def mock_env(monkeypatch):    """    Automatically-applied fixture to mock environment variables before each test runs.    Ensures a controlled and isolated test environment for DB connection logic.    """    monkeypatch.setenv("DB_STRING", "mongodb://example.invalid:27017/")    monkeypatch.setenv("DB_NAME", "mockdb")    monkeypatch.setenv("DB_PASSWORD", "mockpass")# ----------------------------- Unit Tests ----------------------------- #def test_successful_connection():    """Simulate a successful DB connection by mocking MongoClient.ping."""    with patch("pymongo.MongoClient") as mock_client:        mock_instance = MagicMock()        mock_instance.admin.command.return_value = {"ok": 1}  # Simulate success ping        mock_client.return_value = mock_instance        db = Database()  # Trigger connection logic        assert db.db is not None  # Confirm the DB was setdef test_failed_authentication():    """Simulate authentication failure using OperationFailure and expect custom exception."""    with patch("pymongo.MongoClient") as mock_client:        mock_instance = MagicMock()        mock_instance.admin.command.side_effect = pymongo.errors.OperationFailure("Auth failed")        mock_client.return_value = mock_instance        with pytest.raises(DatabaseConnectionError):            Database()  # Should raise our custom connection errordef test_add_record_success():    """Test that a document is successfully inserted and the correct ID is returned."""    with patch("pymongo.MongoClient") as mock_client:        mock_db = MagicMock()        mock_collection = MagicMock()        mock_collection.insert_one.return_value.inserted_id = "1234"  # Simulate insert return        # Connect collection to DB mock        mock_db.__getitem__.return_value = mock_collection        mock_client.return_value.__getitem__.return_value = mock_db        mock_client.return_value.admin.command.return_value = {"ok": 1}  # Simulate ping
